from fastapi import FastAPI
from fastapi.sse import ServerSentEvent, EventSourceResponse
from fastapi.testclient import TestClient
import pytest

app = FastAPI()

@app.get("/sse")
async def sse_endpoint():
    async def event_generator():
        yield ServerSentEvent(event="hello\nworld", data="test")
    return EventSourceResponse(event_generator())

client = TestClient(app)

def test_sse_newline_event():
    response = client.get("/sse")
    try:
        list(response.iter_lines())
    except Exception as e:
        print(f"Caught expected exception: {e}")
        return
    pytest.fail("Should have raised an exception for newline in event")

def test_sse_newline_id():
    @app.get("/sse-id")
    async def sse_id_endpoint():
        async def event_generator():
            yield ServerSentEvent(id="id\n123", data="test")
        return EventSourceResponse(event_generator())

    response = client.get("/sse-id")
    try:
        list(response.iter_lines())
    except Exception as e:
        print(f"Caught expected exception: {e}")
        return
    pytest.fail("Should have raised an exception for newline in id")

if __name__ == "__main__":
    # Run the tests
    import pytest
    pytest.main([__file__])

